"use strict";(self.webpackChunk_rspress_docs=self.webpackChunk_rspress_docs||[]).push([["464"],{9521:function(n,e,r){r.r(e),r.d(e,{default:()=>c});var d=r(1549),h=r(5743);function s(n){let e=Object.assign({p:"p",h2:"h2",a:"a",strong:"strong"},(0,h.a)(),n.components);return(0,d.jsxs)(d.Fragment,{children:[(0,d.jsx)(e.p,{children:"最近下了一个定义，即“所有的能力都是感受能力”，写一篇文章记录下我的想法。"}),"\n",(0,d.jsxs)(e.h2,{id:"项目管理工具是提升对项目感受的手段",children:["项目管理工具是提升对项目感受的手段",(0,d.jsx)(e.a,{className:"header-anchor","aria-hidden":"true",href:"#项目管理工具是提升对项目感受的手段",children:"#"})]}),"\n",(0,d.jsx)(e.p,{children:"之前做项目管理，为了厘清项目内容，进度，人力安排，花很大代价做了一些表，希望能用这些工具来厘清进度，帮助我更好的管理项目。"}),"\n",(0,d.jsx)(e.p,{children:"后来发现，领导哪怕不做这些表，仍然能对这些项目有很多的了解，依然能说的上项目的主要人力，主要进度。"}),"\n",(0,d.jsx)(e.p,{children:"后来我就在想，我和领导差在哪呢？"}),"\n",(0,d.jsx)(e.p,{children:"前两天看书，突然想明白了。差别在于感受。管理工具只是为了强化感受，而不能取代人去实现项目管理。领导对项目存在大量的隐性知识，简单一些的，比如这个项目怎么来的，先后经过了哪些发展。再比如参与这个项目的其他人技术如何，做事风格如何。复杂一些的，比如当前项目发展到了哪些阶段，属于开发多还是维护多。"}),"\n",(0,d.jsx)(e.p,{children:"这些项目背后的潜在知识我在刚上手的时候很难一下子捋清楚，但是对领导来说，这是他本身就掌握的基础。所以他可以看着一个进展文字汇报就知道事情发展所属的阶段，往后可能会有什么风险，之类。但我在此基础上则缺少对项目进度的把控，往往在到项目截止前才会发现进度存在问题。"}),"\n",(0,d.jsx)(e.p,{children:"如果对项目的感受深，那一天花一点点时间了解就可以了。但如果不甚了解，而且了解的层次始终不够，那每天会花更多时间，导致潜在的“浪费”。"}),"\n",(0,d.jsx)(e.p,{children:"这次反思后，我又一次加深了对“以人为本”的理解。任何项目管理工具，使用它们的目的是为了提高人对项目的认识，从而能更好的实施管理操作。"}),"\n",(0,d.jsxs)(e.p,{children:["所以",(0,d.jsx)(e.strong,{children:"管理工具不是银弹"}),"，不是说只要有了足够好的工具，是个人就可以去管。即使工具有能力让人更好的完成项目总览，项目规划等操作，但具体的管理实施行为仍然要在感受的基础上完成。对项目的感受不够深，操作再方便，也会导致项目管理失败。"]}),"\n",(0,d.jsxs)(e.h2,{id:"职业能力就是感受能力",children:["职业能力就是感受能力",(0,d.jsx)(e.a,{className:"header-anchor","aria-hidden":"true",href:"#职业能力就是感受能力",children:"#"})]}),"\n",(0,d.jsx)(e.p,{children:"上一节提到的项目管理过程，是项目经理要承担的职责，对应的能力就是项目管理能力。由此就能给出一个定性的衡量项目管理能力的评价标准：能够更快，更全面的掌握一个项目的全局，清楚各种管理操作会带来的变化。而熟练掌握各种工具或者模型只是加分项。如果一个项目经理去面试，按照前者（我对项目的掌控能力）去描述，肯定比后者（我熟练应用各种工具）更能得到认可。"}),"\n",(0,d.jsx)(e.p,{children:"不止于此。所有的职业能力，最后都是特定感受能力的体现。厨师对菜品味道的感受比普通人强，对火候的感受比一般人强，所以才可以当厨师。舞师对身体空间状态的感受，对肌肉的感受比一般人强，所以可以当舞师。所有能被称得上是“职业技能”的能力，最后都十分依赖特定场景下的感受能力。"}),"\n",(0,d.jsx)(e.p,{children:"很多时候我们都是简单的用“能力”“经验”“知识”来评价一个人是否擅长某事。但再往深处去看一看，就会发现，能力，经验，知识，（或者对工具的使用熟练度），最后都是在提高人的感受能力。感受能力才最终决定了一个人能力的强弱。"}),"\n",(0,d.jsx)(e.p,{children:"做任何事，应该都先向内求，而不是向外。能感受到工具间的差异才能挑好工具。清楚自己要做什么才能找到好的工具，用好工具。"}),"\n",(0,d.jsxs)(e.h2,{id:"工具和感受的循环往复",children:["工具和感受的循环往复",(0,d.jsx)(e.a,{className:"header-anchor","aria-hidden":"true",href:"#工具和感受的循环往复",children:"#"})]}),"\n",(0,d.jsx)(e.p,{children:"如果感受能力是一切，那我还需要使用工具吗？工具还需要熟练的使用吗？答案仍然是肯定的。好的工具是可以帮助我们提高感受能力的。"}),"\n",(0,d.jsx)(e.p,{children:"工具提高的感受能力，包括两种。"}),"\n",(0,d.jsx)(e.p,{children:"一种是作为人感受的延伸，带来的直接的感受能力的提高。"}),"\n",(0,d.jsx)(e.p,{children:"另一种是在长期的使用后，对事物本身感受更深刻。这种深刻首先体现在我们能够更有效率的使用工具上，工具会变得更“趁手”。深刻其次体现在，即使脱离工具，我们仍然不会丧失对相关事物的感受能力。"}),"\n",(0,d.jsx)(e.p,{children:"比如，人一开始用尺子测量，用圆规画圆，这两个工具帮助人提高对长度，画圆时的感受能力。但长期使用后，我们不需要小心翼翼的去使用，随便一比就能知道长短，随便画圆规也不会滑动走形。再往后，人眼就变成了尺，人手就变成了规，即使不用，也能十分精确的比出常见长度，用手一圈就是一个圆。数学老师大多都有这种能力。"}),"\n",(0,d.jsx)(e.p,{children:"认识工具，使用工具，基于工具认识世界，再脱离工具认识世界，基于对事物的认识进一步的改造工具。这是本节对《实践论》的一个扩写。"}),"\n",(0,d.jsxs)(e.h2,{id:"优先追求一个领域的极致",children:["优先追求一个领域的极致",(0,d.jsx)(e.a,{className:"header-anchor","aria-hidden":"true",href:"#优先追求一个领域的极致",children:"#"})]}),"\n",(0,d.jsx)(e.p,{children:"在一个领域追求极致的过程，会让人在所有领域都受益。这个关系是普遍存在的。"}),"\n",(0,d.jsx)(e.p,{children:"一个人在任何领域发展，总会遇到瓶颈。这个瓶颈会让有追求的人苦思冥想，寝食难安，希望能有突破。他可能会疯狂的练习，或询问导师，或翻看书籍。最后成功，或者失败。"}),"\n",(0,d.jsx)(e.p,{children:"如果有一个职业，可以在你遇到瓶颈的时候，指点你更快的突破，那这个“瓶颈突破师”，应该具备什么能力呢？"}),"\n",(0,d.jsx)(e.p,{children:"我们会发现一些体校的教练会担任一部分这种角色。在这种时候，教练往往清楚突破了瓶颈之后这个人是什么样的（各个位置肌肉力量应该如何，动作应该如何），同时也通过观察清楚了你的现状是如何的。在此基础上，他可以指点你去锻炼某个地方的肌肉，或者调整某些地方的发力。这个指点往往很有效。即使教练可能不分析直接给出结论，学员会很懵逼，甚至不相信，但只要做了，往往都会很有效。"}),"\n",(0,d.jsx)(e.p,{children:"从这个例子回来，我们可以总结“瓶颈突破师”需要的能力：能精准的描述。能精准的描述未来瓶颈突破后的状况。能精准的规划当前到预期的路线。"}),"\n",(0,d.jsx)(e.p,{children:"当列出来后我们会发现，这不就是我们日常在做的事情吗？是的，任何行业想做好，都需要脚踏实地，订好目标，列好计划。这是所有能力的元能力，而这些元能力仍然依赖于感受能力。对现状的感受，对不满的感受，对路线的感受。"}),"\n",(0,d.jsx)(e.p,{children:"当我们遇到瓶颈的时候，往往是这三者里有一项或者多项不清晰的时候。"}),"\n",(0,d.jsx)(e.p,{children:"而每次我们突破瓶颈，不管这三者是否清晰，但我们都经过了某个到达预期的路线。"}),"\n",(0,d.jsx)(e.p,{children:"每次突破瓶颈，在你感受到后的，都会有一个巨大的反馈。当突破的次数多了，这种反馈会让你逐渐建立更高层次的感受，从而在遇到瓶颈的时候，能直接感受到：我是在哪些地方不够才遇到瓶颈的，我是还没有走哪条路才遇到瓶颈的。"}),"\n",(0,d.jsx)(e.p,{children:"这种重要的能力即使换一种行业，也仍然会让你受益。"}),"\n",(0,d.jsx)(e.p,{children:"所以，有人指点总是幸事，苦思冥想一朝顿悟也称不上不幸。打不倒你的一切终将助你前行。"}),"\n",(0,d.jsxs)(e.h2,{id:"ai能代替人吗",children:["AI能代替人吗？",(0,d.jsx)(e.a,{className:"header-anchor","aria-hidden":"true",href:"#ai能代替人吗",children:"#"})]}),"\n",(0,d.jsxs)(e.h2,{id:"附录认识还是感受",children:["附录：认识还是感受？",(0,d.jsx)(e.a,{className:"header-anchor","aria-hidden":"true",href:"#附录认识还是感受",children:"#"})]}),"\n",(0,d.jsx)(e.p,{children:"在写的时候我一度纠结“感受”和“认识”这两个词的使用。"}),"\n",(0,d.jsx)(e.p,{children:"人的所有活动都归结到两种：认识世界和改造世界。其中认识世界又包括了感性认识和理性认识。那为什么感受能力不写成认识能力呢？"}),"\n",(0,d.jsx)(e.p,{children:"抿一下这两个词，会发现，“感受”更多是外物向内走，而“认识”则更多是主动向外探寻。"}),"\n",(0,d.jsx)(e.p,{children:"我们会发现，人通过身体感受世界，先天具有短板。但人又天生具备通过不断训练，超越自身短板的能力。而工具，则是让我们没有短板的"}),"\n",(0,d.jsx)(e.p,{children:"可能有人天生对特定事物感受能力强，但大多数人都是普通人，仍然需要接触事物才能有感受。而大多数事物，是不会“说话”的。我们往往只见表象，而看不清内在。"}),"\n",(0,d.jsx)(e.p,{children:"而工具就是人感受能力的延伸。尺子帮助人建立对长度的感知，时钟帮助人建立人对时间的感知。。。在此基础上，人对运动，速度才有了更精确的感受，才有办法建立起更精密的物理学。x光让人的身体内部结构展现出来，让医生能更好的感受病人的身体内在，得以更有效的治疗。"}),"\n",(0,d.jsx)(e.p,{children:"工具一方面帮助人感知，另一方面，熟练使用工具也能减轻人在特殊事项上的心智负担，让人可以把更多的时间放到更核心的事情上去。"}),"\n",(0,d.jsx)(e.p,{children:"一个厨师可以用大勺精确的“挖”出“适量”的调料，但新手根据菜谱，用电子秤也可以完成“适量”的调料。工具在这里让新手减少了调料的一部分心智负担，让他能更加专注于火候的控制。"}),"\n",(0,d.jsx)(e.p,{children:"感受能力的提高后，对工具本身，也会有更好的理解。"}),"\n",(0,d.jsx)(e.p,{children:"我个人的经验，成功突破瓶颈一般有两种感觉。一种是当场醍醐灌顶，仿佛神经元突然连接到一起。另一种是事后察觉，意识到了自己现在和之前出现了一些区别。"}),"\n",(0,d.jsx)(e.p,{children:"如果将这个过程变成职业，那应该就是“瓶颈突破师”。“瓶颈突破师”的能力，就是感受突破瓶颈前后差异的能力。如果他能知道我突破了之后应该是什么样子，朝什么方向努力可以突破，那突破就是水到渠成的事，有追求的人不缺这点努力。"}),"\n",(0,d.jsx)(e.p,{children:"当一个人突破了一次瓶颈，并且有了这个认识，那下一次遇到瓶颈，就会进一步的感受他的缺点，更快的完成突破。"}),"\n",(0,d.jsx)(e.p,{children:"当一个人真的成为了职业“瓶颈突破师”，那他去任何一个行业，都能快速成长，快速突破。"}),"\n",(0,d.jsxs)(e.h2,{id:"感受还是认识",children:["感受还是认识？",(0,d.jsx)(e.a,{className:"header-anchor","aria-hidden":"true",href:"#感受还是认识",children:"#"})]}),"\n",(0,d.jsx)(e.p,{children:"感受和认识的区别是什么？我可以用认识代替感受吗？我可以用理性认识代替感受吗？"}),"\n",(0,d.jsx)(e.p,{children:"认识分为理性认识和感性认识，这两个词在语言中，可以单独拿出来区分，但在实际的认识过程中，这两者是同时起到作用。对这两者，只能定性的察觉到哪种认识多，哪种认识少，而无法定量的测量具体的值。"}),"\n",(0,d.jsx)(e.p,{children:"感受是认识的一部分。感受首先作为一种信息，提供了外界基于感官对我们内心的直接反馈，这是认识的基础。在这个过程中，感受陆续影响情绪、触发记忆，最终决定我们的认识。"}),"\n",(0,d.jsx)(e.p,{children:"感受能力不等于认识能力。感受能力更侧重于直接的体验和情感反应，而认识能力则关注于思考和理解的过程。"}),"\n",(0,d.jsx)(e.p,{children:"所有的感受都是一种认识，所有的认识不全都是感受。，但感受能力不完全等同于认识能力"})]})}function i(){let n=arguments.length>0&&void 0!==arguments[0]?arguments[0]:{},{wrapper:e}=Object.assign({},(0,h.a)(),n.components);return e?(0,d.jsx)(e,{...n,children:(0,d.jsx)(s,{...n})}):s(n)}let c=i;i.__RSPRESS_PAGE_META={},i.__RSPRESS_PAGE_META["0001-Blogs%2F2025%2F2025.03.17-%E6%89%80%E6%9C%89%E7%9A%84%E8%83%BD%E5%8A%9B%E9%83%BD%E6%98%AF%E6%84%9F%E5%8F%97%E8%83%BD%E5%8A%9B.md"]={toc:[{text:"项目管理工具是提升对项目感受的手段",id:"项目管理工具是提升对项目感受的手段",depth:2},{text:"职业能力就是感受能力",id:"职业能力就是感受能力",depth:2},{text:"工具和感受的循环往复",id:"工具和感受的循环往复",depth:2},{text:"优先追求一个领域的极致",id:"优先追求一个领域的极致",depth:2},{text:"AI能代替人吗？",id:"ai能代替人吗",depth:2},{text:"附录：认识还是感受？",id:"附录认识还是感受",depth:2},{text:"感受还是认识？",id:"感受还是认识",depth:2}],title:"所有的能力都是感受能力",headingTitle:"",frontmatter:{title:"所有的能力都是感受能力",tags:["思考101"]}}}}]);